inline const StationGeometry* DTGeometryData::GetStationGeometry(G4int wheel, G4int sector, G4int station) const {
    auto it = fGeometryDB.find(MakeKey(wheel, sector, station));
    if (it != fGeometryDB.end()) {
        return &(it->second);
    }
    return nullptr;
}

